Proceso CribaDeEratostenes
    Dimension esCompuesto[101] Como Logico;
    Definir limite Como Entero;
    Definir i Como Entero;
    Definir j Como Entero;
    Leer limite;
    Para i <- 0 Hasta 100 Con Paso 1 Hacer
        esCompuesto[i] <- Falso;
    FinPara
    Para i <- 2 Hasta limite Con Paso 1 Hacer
        Si esCompuesto[i] = Falso Entonces
            Escribir i;
            Para j <- i * i Hasta limite Con Paso i Hacer
                esCompuesto[j] <- Verdadero;
            FinPara
        FinSi
    FinPara
FinProceso
